// include benchmark-specific definitions (for GEMM)
#include "gemm.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize the arrays A, B, C exactly as in the original C code,
 * but using Halide Funcs and Buffers instead of raw C arrays.
 *
 * Original C loops:
 *   *alpha = 1.5;
 *   *beta  = 1.2;
 *   for (i = 0; i < ni; i++)
 *     for (j = 0; j < nj; j++)
 *       C[i][j] = ((i*j+1) % ni) / ni;
 *   for (i = 0; i < ni; i++)
 *     for (j = 0; j < nk; j++)
 *       A[i][j] = (i*(j+1) % nk) / nk;
 *   for (i = 0; i < nk; i++)
 *     for (j = 0; j < nj; j++)
 *       B[i][j] = (i*(j+2) % nj) / nj;
 *
 * Mapping to Halide Buffers:
 *   Logical shapes:
 *     A: NI x NK
 *     B: NK x NJ
 *     C: NI x NJ
 *
 *   Physical layouts used here:
 *     - C[i][j]  (NI x NJ, row-major)  -> Buffer C(j, i)  of shape (nj, ni)
 *       j is the fast-varying dimension, matching row-major layout.
 *
 *     - A[i][j]  (NI x NK, row-major)  -> Buffer A(k, i)  of shape (nk, ni)
 *       k is the fast-varying dimension (reduction dim), so A is stride‑1 in k.
 *
 *     - B[i][j]  (NK x NJ, row-major)  -> Buffer B(k, j)  of shape (nk, nj)
 *       k is the fast-varying dimension here as well. This makes B stride‑1
 *       in the reduction dimension k for each fixed column j, which greatly
 *       improves locality when iterating over k inside the GEMM reduction.
 */
static void init_array(int ni, int nj, int nk,
                       num_t *alpha,
                       num_t *beta,
                       Halide::Buffer<num_t, 2> C,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B) {
    *alpha = (num_t)1.5;
    *beta  = (num_t)1.2;

    Var i("i"), j("j"), k("k");
    Func init_A("init_A"), init_B("init_B"), init_C("init_C");

    // C[i][j] = ((i*j+1) % ni) / ni;
    // Buffer layout: C(j, i)
    init_C(j, i) = cast<num_t>((i * j + 1) % ni) / cast<int>(ni);

    // A[i][j] = (i*(j+1) % nk) / nk;
    // Buffer layout: A(k, i) where k is the "j" from the C code
    init_A(k, i) = cast<num_t>(i * (k + 1) % nk) / cast<int>(nk);

    // B[i][j] = (i*(j+2) % nj) / nj;
    // Buffer layout: B(k, j) where k is "i" from the C code, j is j.
    // This stores B with k as the fast-varying dimension (column-major
    // with respect to the original B[k][j]), so that for each fixed j
    // we can iterate over k with stride‑1 memory access.
    init_B(k, j) = cast<num_t>(k * (j + 2) % nj) / cast<int>(nj);

    // Realize initialization into the provided buffers
    init_C.realize(C);
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem sizes (as in PolyBench)
    int ni = NI;
    int nj = NJ;
    int nk = NK;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers:
    //   C: NI x NJ => (width = nj, height = ni)  -> C(j, i)
    //   A: NI x NK => (width = nk, height = ni)  -> A(k, i)
    //   B: NK x NJ => (width = nk, height = nj)  -> B(k, j)
    //
    // Note: B is stored so that k is the fast-varying dimension. This makes
    // accesses B(k, j) over k contiguous in memory for each j, which matches
    // the inner-product pattern in GEMM.
    Halide::Buffer<num_t, 2> C(nj, ni);
    Halide::Buffer<num_t, 2> A(nk, ni);
    Halide::Buffer<num_t, 2> B(nk, nj);

    // ImageParams to represent the input/output images for the Halide pipeline.
    // They share the same logical layout as the Buffers above.
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");

    // Initialize data as in the original C code.
    init_array(ni, nj, nk, &alpha, &beta, C, A, B);

    // Define Vars
    Var i("i"), j("j");

    // Reduction domain over k = 0..nk-1 (the shared dimension of A and B)
    RDom k(0, A.dim(0).extent(), "k");

    // Main GEMM computation:
    //
    // Original C kernel:
    //
    // for (i = 0; i < ni; i++) {
    //   for (j = 0; j < nj; j++)
    //       C[i][j] *= beta;
    //   for (k = 0; k < nk; k++) {
    //      for (j = 0; j < nj; j++)
    //         C[i][j] += alpha * A[i][k] * B[k][j];
    //   }
    // }
    //
    // This is equivalent to:
    //   C[i][j] = beta * C[i][j] +
    //             sum_{k=0..nk-1}(alpha * A[i][k] * B[k][j]);
    //
    // Mapping to Halide coordinates with our layouts:
    //   C(i,j) => C_param(j, i)
    //   A(i,k) => A_param(k, i)
    //   B(k,j) => B_param(k, j)
    //
    // We'll implement C := beta*C + alpha*A*B using a reduction.
    Func gemm("gemm");

    // Pure definition: initialize each output element with beta * C
    gemm(j, i) = Expr(beta) * C_param(j, i);

    // Update definition: accumulate alpha * A * B over k
    gemm(j, i) += Expr(alpha) * A_param(k, i) * B_param(k, j);

    // ----------------------
    // Optimized scheduling
    // ----------------------
    //
    // Goal (based on the provided optimization models):
    //   - Improve data locality via 3D blocking (i, j, k).
    //   - Exploit SIMD by vectorizing along the contiguous j dimension.
    //   - Exploit multi-core parallelism by parallelizing over tiles in i.
    //   - Keep A and B accesses cache-friendly:
    //       * A(k, i): stride‑1 in k for fixed i.
    //       * B(k, j): stride‑1 in k for fixed j (due to our B layout).
    //
    // We tile i (rows of C) and j (columns of C), and also tile the reduction
    // dimension k. The tile sizes can be tuned; here we choose conservative
    // defaults and size the j‑tile as a multiple of the hardware SIMD width.

    Target target = get_host_target();

    // Natural SIMD width for the current target and element type
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width <= 0) {
        vec_width = 1;
    }

    // Tile sizes (can be tuned per target; chosen to be reasonable defaults)
    const int tile_i = 32;                 // rows of C per tile
    const int tile_j = vec_width * 8;      // cols of C per tile, multiple of SIMD width
    const int tile_k = 32;                 // depth of k per tile
    const int unroll_k = 4;                // unroll factor for inner k

    Var io("io"), jo("jo"), ii("ii"), jj("jj");
    RVar ko("ko"), ki("ki");

    // Compute the entire GEMM at root.
    gemm.compute_root();

    // --- Schedule for the pure definition (C = beta * C) ---
    //
    // Tile (i, j) so that we work on cache-friendly blocks of C.
    // Loop order inside tiles: io (outer i-tiles), jo (j-tiles), ii, jj.
    // We parallelize across i-tiles and vectorize across columns (jj).
    gemm
        .tile(j, i, jo, io, jj, ii, tile_j, tile_i, TailStrategy::GuardWithIf)
        .reorder(jj, ii, jo, io)   // innermost to outermost
        .parallel(io)              // parallel over tiles in i
        .vectorize(jj, vec_width); // SIMD over contiguous j

    // --- Schedule for the reduction update (C += alpha * A*B) ---
    //
    // We use the same tiling over (i, j) as for the pure definition,
    // then further split the reduction variable k into ko and ki to
    // get 3D blocking (i, j, k). The reduction is carried out as:
    //
    //   for io, jo, ii, jj:
    //     for ko:
    //       for ki:
    //         ... accumulate over k = ko*tile_k + ki ...
    //
    // Access patterns:
    //   - A_param(k, i): for fixed (i), we traverse k contiguously.
    //   - B_param(k, j): for fixed (j), we traverse k contiguously.
    //   - C/gemm(j, i): updated in TI x TJ tiles, fitting better in cache.
    gemm.update()
        .tile(j, i, jo, io, jj, ii, tile_j, tile_i, TailStrategy::GuardWithIf)
        .split(k, ko, ki, tile_k, TailStrategy::GuardWithIf)
        // Loop order (innermost to outermost): jj [SIMD], ki [unrolled k],
        // ii, ko (k-tiles), jo (j-tiles), io (i-tiles).
        .reorder(jj, ki, ii, ko, jo, io)
        .parallel(io)
        .vectorize(jj, vec_width)
        .unroll(ki, unroll_k);

    // Bind the ImageParams to the concrete Buffers
    C_param.set(C);
    A_param.set(A);
    B_param.set(B);

    // Compile the kernel to machine code (JIT) for the chosen target
    gemm.compile_jit(target);

    // Measure execution time of the GEMM kernel
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write the result into C
    gemm.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the resulting C, similar to PolyBench's print_array.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nj; jj++) {
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    // Print timing in seconds to stdout
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
