    // A[i][j] = (i*(j+1) % nk) / nk;
    // Buffer layout: A(k, i) where k is the "j" from the C code
    init_A(k, i) = cast<num_t>(i * (k + 1) % nk) / cast<int>(nk);

    // B[i][j] = (i*(j+2) % nj) / nj;
    // Buffer layout: B(j, k) where i in C code is our k, and j is j
    init_B(j, k) = cast<num_t>(k * (j + 2) % nj) / cast<int>(nj);

    // The initialization cost is tiny compared to GEMM, so we just use
    // the default (root) schedules here for clarity.
    init_C.realize(C);
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem sizes (as in PolyBench)
    int ni = NI;
    int nj = NJ;
    int nk = NK;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers:
    //   C: NI x NJ => (width = nj, height = ni)
    //   A: NI x NK => (width = nk, height = ni)
    //   B: NK x NJ => (width = nj, height = nk)  (rows indexed by k, cols by j)
    Halide::Buffer<num_t, 2> C(nj, ni);
    Halide::Buffer<num_t, 2> B(nj, nk);
    Halide::Buffer<num_t, 2> A(nk, ni);

    // ImageParams to represent the input/output images for the Halide pipeline.
    // They share the same logical layout as the Buffers above.
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");

    // Initialize data as in the original C code.
    init_array(ni, nj, nk, &alpha, &beta, C, A, B);

    // Define Vars
    Var i("i"), j("j");

    // Reduction domain over k = 0..nk-1 (the shared dimension of A and B)
    RDom k(0, A.dim(0).extent(), "k");  // extent == nk

    // Main GEMM computation:
    //
    // Original C kernel (PolyBench variant):
    //
    // for (i = 0; i < ni; i++) {
    //   for (j = 0; j < nj; j++)
    //       C[i][j] *= beta;
    //   for (k = 0; k < nk; k++) {
    //      for (j = 0; j < nj; j++)
    //         C[i][j] += alpha * A[i][k] * B[k][j];
    //   }
    // }
    //
    // This is equivalent to:
    //   C[i][j] = beta * C[i][j] +
    //             sum_{k=0..nk-1}(alpha * A[i][k] * B[k][j]);
    //
    // Mapping to Halide coordinates:
    //   C(i,j) => C_param(j, i)
    //   A(i,k) => A_param(k, i)
    //   B(k,j) => B_param(j, k)
    //
    // We'll implement C := beta*C + alpha*A*B using a single reduction Func.
    Func gemm("gemm");

    // Pure definition: initialize each output element with beta * C
    gemm(j, i) = Expr(beta) * C_param(j, i);

    // Update definition: accumulate alpha * A * B over k
    gemm(j, i) += Expr(alpha) * A_param(k, i) * B_param(j, k);

    // ------------------------------------------------------------------
    // Optimized schedule
    // ------------------------------------------------------------------
    //
    // Goal:
    //   - Good data locality in all three matrices via 3D blocking.
    //   - Exploit 32 cores via parallelization across output tiles.
    //   - Exploit SIMD via vectorization along j (the stride-1 dimension).
    //   - Exploit ILP via unrolling of the reduction over k.
    //
    // Memory layout recap:
    //   A: Buffer A(k, i)      -> logical A[i][k], row-major in k
    //   B: Buffer B(j, k)      -> logical B[k][j], row-major in j
    //   C: Buffer C(j, i)      -> logical C[i][j], row-major in j
    //
    // For the update we will iterate k outside i/j tiles, with j innermost:
    //   for each tile of rows (i) and cols (j):
    //     for each k-tile:
    //       for each k in that tile:
    //         for each i in row-tile:
    //           for each j in col-tile (vectorized):
    //             C[i,j] += alpha * A[i,k] * B[k,j]
    //
    // This streaming order gives:
    //   - A[i,k]   : k outer, i inner    -> stride-1 in k for each row of A
    //   - B[k,j]   : k outer, j inner   -> stride-1 in j for each row k of B
    //   - C[i,j]   : i & j inner        -> stride-1 in j for C rows
    //
    // and reuses A and B tiles effectively in caches.

    // Pick a reasonable target-dependent SIMD width.
    Target target = get_host_target();
    int vec_width = natural_vector_size(type_of<num_t>(), target);
    if (vec_width < 1) {
        vec_width = 1;
    }

    // Tile sizes; tuned for a moderately large CPU (32 cores, typical caches).
    // These are conservative defaults; for different problem sizes or CPUs
    // they can be adjusted.
    const int tile_i = 64;  // number of rows of C per tile
    const int tile_j = 64;  // number of cols of C per tile
    const int tile_k = 32;  // depth of the k-tile

    // Tiled variables for i and j, and split reduction vars for k.
    Var io("io"), jo("jo"), ii("ii"), ji("ji");
    RVar ko("ko"), ki("ki");

    // Make it explicit that gemm is computed at root (default, but clearer).
    gemm.compute_root();

    // --- Schedule for the pure (initialization) step ---
    //
    // Scale C by beta in tiles of size tile_i x tile_j.
    // Layout after tile(j, i, ...):
    //   for io (y_outer over i):
    //     for jo (x_outer over j):
    //       for ii (inner i in tile):
    //         for ji (inner j in tile, innermost and vectorized):
    gemm
        .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
        // Parallelize across tiles of rows (io), which are independent.
        .parallel(io)
        // Vectorize the innermost j-dimension for SIMD.
        .vectorize(ji, vec_width);

    // --- Schedule for the update (reduction) step ---
    //
    // We apply the same 2D tiling for (i, j), then split the reduction
    // over k into ko (outer tile in k) and ki (inner within a tile).
    // Loop order inside the update (from outermost to innermost) will be:
    //   io (row tiles, parallel)
    //     jo (column tiles)
    //       ko (k tiles)
    //         ki (k within tile, optionally unrolled)
    //           ii (rows within tile)
    //             ji (columns within tile, vectorized)
    gemm.update()
        .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
        .split(k, ko, ki, tile_k)
        // Reorder loops; arguments are listed from innermost to outermost.
        // This gives outer-to-inner: io -> jo -> ko -> ki -> ii -> ji.
        .reorder(ji, ii, ki, ko, jo, io)
        .parallel(io)
        .vectorize(ji, vec_width)
        // Unroll a few iterations of ki inside the k-tile for ILP.
        .unroll(ki);

    // Bind the ImageParams to the concrete Buffers
    C_param.set(C);
    A_param.set(A);
    B_param.set(B);

    // Compile the kernel to machine code (JIT) for the chosen target
    gemm.compile_jit(target);

    // Measure execution time of the GEMM kernel
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write the result into C
    gemm.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the resulting C, similar to PolyBench's print_array.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nj; jj++) {
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    // Print timing in seconds to stdout
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
