    //      for io, jo   over tiles
    //        for ii, ji over points within a tile
    //  - fuse(jo, io, tile) combines tile indices into a single loop var
    //    so we can parallelize over tiles without nested parallelism.
    //  - parallel(tile) runs independent tiles on different threads.
    //  - vectorize(ji) uses SIMD across contiguous j values within a tile.
    gemm
        .tile(j, i, jo, io, ji, ii,
              tile_j, tile_i, TailStrategy::GuardWithIf)
        .fuse(jo, io, tile)
        .parallel(tile)
        .vectorize(ji, vec_width);

    // Schedule for the reduction update (accumulation over k):
    //
    //  - We apply the same 2D tiling over (j, i) and fuse tile indices.
    //  - Loop order inside each tile:
    //        tile (parallel)
    //          ii   (rows within tile)
    //            k  (reduction dimension)
    //              ji (vectorized columns within tile, innermost)
    //
    //    So for each (tile, ii, k) we compute a SIMD vector over ji,
    //    which yields:
    //      * C_param(j, i) unit-stride across j  (good stores)
    //      * B_param(j, k) unit-stride across j  (good loads)
    //      * A_param(k, i) scalar for this (i, k) pair (broadcast in SIMD)
    //
    //  - We deliberately keep k inside the tile, but outside ji, to maintain
    //    a simple sequential reduction without extra synchronization.
    gemm.update()
        .tile(j, i, jo, io, ji, ii,
              tile_j, tile_i, TailStrategy::GuardWithIf)
        .fuse(jo, io, tile)
        // Reorder so that within each tile:
        //   inner-most:  ji   (vectorized j)
        //   then:        k    (reduction)
        //   then:        ii   (rows)
        //   outer-most:  tile (different tiles in parallel)
        .reorder(ji, k, ii, tile)
        .parallel(tile)
        .vectorize(ji, vec_width);

    // Bind the ImageParams to the concrete Buffers
    C_param.set(C);
    A_param.set(A);
    B_param.set(B);

    // Compile the kernel to machine code (JIT) for the chosen target
    gemm.compile_jit(target);

    // Measure execution time of the GEMM kernel
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write the result into C
    gemm.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the resulting C, similar to PolyBench's print_array.
    // Here we just print all values to stderr when invoked with any argv[0] (always true),
    // but keep the check to mirror the example structure.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nj; jj++) {
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    // Print timing in seconds to stdout
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
